<script lang="ts">
  import {refreshAll} from '$app/navigation';import {command,display} from '#lib/client/api.ts';import type {AppData} from '#lib/client/types.ts';import Icon from './Icon.svelte';
  let {data,initialOrderId='',activity=''}:{data:AppData;initialOrderId?:string;activity?:string}=$props();let selectedOrder=$state('');let workPackage=$state('');let performedOn=$state(new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date()));let description=$state('');let quantity=$state('');let unit=$state('piece');let busy=$state(false);let error=$state('');let notice=$state('');let reportSaved=$state(false);
  async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';notice='';try{const orderId=selectedOrder||initialOrderId;if(!orderId)throw new Error('Wählen Sie bitte den Auftrag aus, zu dem die Leistung gehört.');if(!reportSaved){await command('workforce.time.report',undefined,{order_id:orderId,work_package_id:workPackage||undefined,performed_on:performedOn,description});reportSaved=true;}if(quantity!=='')await command('workforce.time.quantity',undefined,{order_id:orderId,work_package_id:workPackage||undefined,performed_on:performedOn,quantity,unit,activity:activity||description});description='';quantity='';reportSaved=false;notice='Ihr Bericht und die angegebene Leistungsmenge wurden gespeichert.';await refreshAll().catch(()=>{});}catch(e){error=(reportSaved?'Der Bericht ist bereits gespeichert. Die Menge konnte noch nicht übernommen werden. ':'')+(e instanceof Error?e.message:'Bitte versuchen Sie es erneut.');}finally{busy=false;}}
</script>
<section class="panel"><header class="panel-header"><div><h2>Was wurde erledigt?</h2><p>Eine kurze Rückmeldung ergänzt Ihre Zeit. Sie können sie auch später nachtragen.</p></div><Icon name="pen" size={18}/></header><form class="panel-body" onsubmit={save}>{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}<div class="field-grid"><div class="field"><label for="report-order">Auftrag *</label><select id="report-order" value={selectedOrder||initialOrderId} onchange={e=>selectedOrder=e.currentTarget.value} required disabled={reportSaved}><option value="">Auftrag auswählen</option>{#each data.lookups?.orders||[] as order}<option value={order.id}>{order.name}</option>{/each}</select><span class="field-help">Wählen Sie den Auftrag, an dem Sie tatsächlich gearbeitet haben.</span></div><div class="field"><label for="report-performed">Leistungstag *</label><input id="report-performed" type="date" bind:value={performedOn} required disabled={reportSaved}/></div>{#if data.lookups?.['work-packages']?.length}<div class="field full"><label for="report-package">Arbeitspaket · optional</label><select id="report-package" bind:value={workPackage} disabled={reportSaved}><option value="">Gesamter Auftrag</option>{#each data.lookups['work-packages'] as work}<option value={work.id}>{work.name}</option>{/each}</select></div>{/if}<div class="field full"><label for="report-description">Ihre Rückmeldung *</label><textarea id="report-description" bind:value={description} required minlength="3" disabled={reportSaved} placeholder="Zum Beispiel: Aufmaß im Erdgeschoss abgeschlossen. Eine Anschlussposition ist noch mit dem Kunden zu klären."></textarea><span class="field-help">Was ist fertig, was ist offen? Eine kurze sachliche Beschreibung genügt.</span></div><div class="field"><label for="report-quantity">Erbrachte Menge · optional</label><input id="report-quantity" inputmode="decimal" bind:value={quantity}/><span class="field-help">Zum Beispiel 3,5. Die Menge ist von Ihrer Arbeitszeit getrennt.</span></div><div class="field"><label for="report-unit">Passende Einheit</label><select id="report-unit" bind:value={unit}><option value="piece">Stück</option><option value="m">Meter</option><option value="m2">Quadratmeter</option><option value="m3">Kubikmeter</option><option value="kg">Kilogramm</option><option value="h">Stunden</option><option value="package">Pauschale</option></select></div></div><button type="submit" class="btn primary mt" disabled={busy}>{busy?'Wird gespeichert …':reportSaved?'Offene Menge speichern':'Rückmeldung speichern'}<Icon name="check" size={16}/></button><p class="field-help mt">Die Rückmeldung benötigt eine Serververbindung. Ihre lokale Zeiterfassung können Sie davon unabhängig fortsetzen.</p></form>{#if data.related?.work_reports?.length}<div class="panel-body" style="border-top:1px solid var(--line)"><h3 style="font-size:16px;margin-bottom:20px">Meine letzten Rückmeldungen</h3>{#each data.related.work_reports.slice(0,8) as report}<article class="timeline-item"><h3>{display(report.order_id,'order_id',data)}</h3><p>{display(report.performed_on,'date')}</p><p style="white-space:pre-wrap">{report.description}</p></article>{/each}</div>{/if}{#if data.related?.time_quantity_entries?.length}<div class="panel-body" style="border-top:1px solid var(--line)"><h3 style="font-size:16px;margin-bottom:18px">Meine letzten Leistungsangaben</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Tag</th><th>Auftrag</th><th>Menge</th><th>Leistung</th></tr></thead><tbody>{#each data.related.time_quantity_entries.slice(0,10) as entry}<tr><td>{display(entry.performed_on,'date')}</td><td>{display(entry.order_id,'order_id',data)}</td><td>{display(entry.quantity,'quantity')} {display(entry.unit)}</td><td>{display(entry.activity,'activity')}</td></tr>{/each}</tbody></table></div></div>{/if}</section>
